/*
 * store.js — encrypted, on-device storage for everything a person writes.
 *
 * Key
 *   Native:  a random 256-bit key generated on first launch with crypto.getRandomValues, kept in the
 *            iOS Keychain (this device only, not iCloud-synced) / Android Keystore-backed storage via
 *            @aparajita/capacitor-secure-storage. Imported into Web Crypto as a NON-extractable key.
 *   Browser: a NON-extractable AES-GCM key generated by Web Crypto and kept in IndexedDB. The raw key
 *            bytes are never visible to script. (Weaker than native: see README.)
 *   No key is ever hard-coded, logged or exported.
 *
 * Data
 *   state.enc        'AOS2' + 12-byte IV + AES-256-GCM(JSON {schemaVersion, savedAt, data})
 *   media/<id>       'AOM1' + repeated [u32 length][12-byte IV][AES-256-GCM(chunk)] (1 MB chunks)
 *   Native files live in Library/AnxiouslyOkay (iOS, excluded from backup) or the app's private
 *   files dir (Android, backups disabled). Browser files live in IndexedDB.
 */
(function () {
  'use strict';
  var P = window.AOPlatform;
  var SCHEMA = 2;
  var STATE = 'state.enc';
  var CHUNK = 1024 * 1024;
  var MAGIC_S = [0x41, 0x4F, 0x53, 0x32];   // "AOS2"
  var MAGIC_M = [0x41, 0x4F, 0x4D, 0x31];   // "AOM1"
  var subtle = window.crypto && window.crypto.subtle;
  var key = null, mode = 'none';             // 'native' | 'browser' | 'memory'
  var enc = new TextEncoder(), dec = new TextDecoder();

  function err(code, msg) { var e = new Error(msg || code); e.code = code; return e; }
  function isQuota(e) {
    if (!e) return false;
    var s = String((e.name || '') + ' ' + (e.message || '') + ' ' + (e.code || ''));
    return /Quota|ENOSPC|space|full|22|1014/i.test(s);
  }
  function hasMagic(u8, m) { return u8 && u8.length >= 4 && u8[0] === m[0] && u8[1] === m[1] && u8[2] === m[2] && u8[3] === m[3]; }

  function encryptBytes(u8) {
    var iv = crypto.getRandomValues(new Uint8Array(12));
    return subtle.encrypt({ name: 'AES-GCM', iv: iv }, key, u8).then(function (ct) {
      var out = new Uint8Array(12 + ct.byteLength); out.set(iv, 0); out.set(new Uint8Array(ct), 12); return out;
    });
  }
  function decryptBytes(u8) {
    return subtle.decrypt({ name: 'AES-GCM', iv: u8.subarray(0, 12) }, key, u8.subarray(12)).then(function (pt) { return new Uint8Array(pt); });
  }

  /* ---------- key ---------- */
  function init() {
    if (!subtle || !P) { mode = 'memory'; return Promise.resolve({ mode: mode }); }
    if (P.isNative()) {
      return P.secret.get('dek').then(function (raw) {
        if (raw) return raw;
        /* Encrypted data but no key (e.g. keychain reset): never silently start over on top of it. */
        return P.files.load(STATE).then(function (existing) {
          if (existing) throw err('key-missing');
          var b = crypto.getRandomValues(new Uint8Array(32)), b64 = P.b64FromBytes(b); b.fill(0);
          return P.secret.set('dek', b64).then(function () { return P.secret.get('dek'); }).then(function (back) {
            if (back !== b64) throw err('key-write');
            return b64;
          });
        });
      }).then(function (b64) {
        var kb = P.bytesFromB64(b64);
        return subtle.importKey('raw', kb, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']).then(function (k) { kb.fill(0); key = k; mode = 'native'; return { mode: mode }; });
      });
    }
    return P.idb.get('kv', 'key').then(function (k) {
      if (k) return k;
      return P.files.load(STATE).then(function (existing) {
        if (existing) throw err('key-missing');
        return subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']).then(function (nk) {
          return P.idb.put('kv', 'key', nk).then(function () { return nk; });
        });
      });
    }).then(function (k) { key = k; mode = 'browser'; return { mode: mode }; }, function (e) {
      if (e && e.code === 'key-missing') throw e;
      /* IndexedDB unavailable (private mode, sandboxed preview): keep a session-only key; nothing persists. */
      return subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']).then(function (nk) { key = nk; mode = 'memory'; return { mode: mode }; });
    });
  }

  /* ---------- serialised writes ---------- */
  var chain = Promise.resolve();
  function enqueue(fn) { var p = chain.then(fn); chain = p.catch(function () {}); return p; }

  function writeState(obj) {
    if (mode === 'memory') return Promise.resolve(false);
    return enqueue(function () {
      var json = JSON.stringify({ schemaVersion: SCHEMA, savedAt: Date.now(), data: obj });
      return encryptBytes(enc.encode(json)).then(function (c) {
        var out = new Uint8Array(4 + c.length); out.set(MAGIC_S, 0); out.set(c, 4);
        return P.files.save(STATE, out);
      }).then(function () { return true; });
    });
  }
  /* resolves {schemaVersion, savedAt, data} or null when nothing has been saved yet */
  function readState() {
    if (mode === 'memory') return Promise.resolve(null);
    return P.files.load(STATE).then(function (u8) {
      if (!u8) return null;
      if (!hasMagic(u8, MAGIC_S)) throw err('unreadable');
      return decryptBytes(u8.subarray(4)).then(function (pt) { return JSON.parse(dec.decode(pt)); }, function () { throw err('unreadable'); });
    });
  }

  /* ---------- debounced saves of the live app state ---------- */
  var saveTimer = null, getter = null, dirty = false, onSaveError = null;
  function queueSave(fn) {
    getter = fn; dirty = true;
    clearTimeout(saveTimer); saveTimer = setTimeout(flush, 300);
  }
  function flush() {
    clearTimeout(saveTimer); saveTimer = null;
    if (!dirty || !getter) return Promise.resolve(true);
    dirty = false;
    return writeState(getter()).then(function () { return true; }, function (e) { if (onSaveError) onSaveError(e); return false; });
  }

  /* ---------- media ---------- */
  function mpath(id) { return 'media/' + id; }
  function saveMedia(id, blob) {
    if (mode === 'memory') return Promise.reject(err('unavailable'));
    var parts = [new Uint8Array(MAGIC_M)], off = 0;
    function next() {
      if (off >= blob.size) return Promise.resolve();
      var slice = blob.slice(off, off + CHUNK); off += CHUNK;
      return slice.arrayBuffer().then(function (ab) { return encryptBytes(new Uint8Array(ab)); }).then(function (c) {
        var h = new Uint8Array(4); new DataView(h.buffer).setUint32(0, c.length); parts.push(h, c); return next();
      });
    }
    return next().then(function () { return P.files.save(mpath(id), new Blob(parts)); });
  }
  function loadMedia(id, type) {
    return P.files.load(mpath(id)).then(function (u8) {
      if (!u8) throw err('missing');
      if (!hasMagic(u8, MAGIC_M)) throw err('unreadable');
      var dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength), pos = 4, jobs = [];
      while (pos < u8.length) { var len = dv.getUint32(pos); pos += 4; jobs.push(decryptBytes(u8.subarray(pos, pos + len))); pos += len; }
      return Promise.all(jobs).then(function (pts) { return new Blob(pts, { type: type || '' }); });
    });
  }
  function removeMedia(id) { return id ? P.files.remove(mpath(id)) : Promise.resolve(); }

  /* ---------- wipe: data, media and the key ---------- */
  function wipe() {
    clearTimeout(saveTimer); dirty = false; getter = null;
    return chain.then(function () { return P.files.clear(); })
      .then(function () { return P.isNative() ? P.secret.remove('dek').catch(function () {}) : null; })
      .then(function () { key = null; mode = 'none'; });
  }

  window.AOStore = {
    SCHEMA: SCHEMA,
    init: init,
    mode: function () { return mode; },
    persistent: function () { return mode === 'native' || mode === 'browser'; },
    readState: readState, writeState: writeState,
    queueSave: queueSave, flush: flush, onSaveError: function (f) { onSaveError = f; },
    saveMedia: saveMedia, loadMedia: loadMedia, removeMedia: removeMedia,
    listFiles: function () { return P.files.list(); },
    wipe: wipe, isQuota: isQuota
  };
})();
